    def local_search(placement):
        # Steepest-descent local search: in each iteration evaluate all
        # single-model moves and pairwise swaps, and apply the single
        # change that most reduces the max KVPR. Repeat until no
        # improving move exists.
        def apply_move(src, m, dst):
            placement[src].remove(m)
            placement[dst].append(m)

        def apply_swap(a, ma, b, mb):
            placement[a].remove(ma)
            placement[b].remove(mb)
            placement[a].append(mb)
            placement[b].append(ma)

        while True:
            best_score = max_kvpr(placement)
            best_move = None
            # Single-model moves
            for src in range(gpu_num):
                for m in list(placement[src]):
                    for dst in range(gpu_num):
                        if dst == src:
                            continue
                        if GPU_MEM_SIZE - sum(x.model_size for x in placement[dst]) - m.model_size <= 0:
                            continue
                        apply_move(src, m, dst)
                        s = max_kvpr(placement)
                        apply_move(dst, m, src)
                        if s < best_score:
                            best_score, best_move = s, ('m', src, m, dst)
            # Pairwise swaps
            for a in range(gpu_num):
                for b in range(a + 1, gpu_num):
                    for ma in list(placement[a]):
                        for mb in list(placement[b]):
                            apply_swap(a, ma, b, mb)
                            s = max_kvpr(placement)
                            apply_swap(b, ma, a, mb)
                            if s < best_score:
                                best_score, best_move = s, ('s', a, ma, b, mb)
            if best_move is None:
                break
            if best_move[0] == 'm':
                _, src, m, dst = best_move
                apply_move(src, m, dst)
            else:
                _, a, ma, b, mb = best_move
                apply_swap(a, ma, b, mb)
        return placement
